class ConfigError(Exception):
    """The caller's problem: the config file is wrong."""

def load(raw):
    try:
        return int(raw["retries"])
    except KeyError as exc:
        # Explicit cause: the traceback shows both, and __cause__ is set.
        raise ConfigError("missing 'retries'") from exc
    except ValueError as exc:
        raise ConfigError(f"retries must be an integer, got {raw['retries']!r}") from exc

try:
    load({"retries": "lots"})
except ConfigError as exc:
    print(type(exc).__name__, "|", exc, "| caused by", type(exc.__cause__).__name__)

