class RepositoryError(Exception):
    """Base for every failure this layer is allowed to raise."""

class AlreadyExists(RepositoryError):
    pass

async def insert_user(conn, email):
    try:
        await conn.execute("insert into users(email) values($1)", email)
    except UniqueViolationError as exc:
        # Callers catch AlreadyExists; the driver's type stays an implementation
        # detail, and 'from exc' keeps the constraint name in the traceback.
        raise AlreadyExists(f"email {email!r} is taken") from exc

def read_config(path):
    handle = open(path)
    try:
        raw = handle.read()
    except OSError as exc:
        raise ConfigError(f"cannot read {path}") from exc
    else:
        # Not in the try: a KeyError here is a parse bug, not a read failure.
        return parse(raw)
    finally:
        handle.close()
